// src/lib/args.ts
function parseArgs(argv) {
  const result = { help: false, version: false, update: false, uninstall: false, force: false };
  const rest = [];
  for (let i2 = 0; i2 < argv.length; i2++) {
    const arg = argv[i2];
    if (arg === "-h" || arg === "--help") {
      result.help = true;
    } else if (arg === "-v" || arg === "--version") {
      result.version = true;
    } else if (arg === "update") {
      result.update = true;
    } else if (arg === "uninstall") {
      result.uninstall = true;
    } else if (arg === "--force" || arg === "-f") {
      result.force = true;
    } else if (arg === "--theme") {
      const value = argv[++i2];
      if (!value || value.startsWith("-")) {
        result.error = "--theme needs a value: system, dark, or light";
        return result;
      }
      if (!isThemeMode(value)) {
        result.error = `unknown theme "${value}" \u2014 use system, dark, or light`;
        return result;
      }
      result.themeMode = value;
    } else if (arg.startsWith("-") && arg !== "-") {
      result.error = `unknown option "${arg}"`;
      return result;
    } else {
      rest.push(arg);
    }
  }
  if (rest.length > 1) {
    result.error = "only one url is supported";
    return result;
  }
  result.initialUrl = rest[0];
  return result;
}

